// Thin client wrapper around the Catalyst Advanced I/O function that
// proxies to Gemini. No API key lives here or anywhere in the frontend —
// the function endpoint is the only thing this file knows about.

const ASSISTANT_FUNCTION_URL =
  process.env.REACT_APP_CATALYST_ASSISTANT_FUNCTION_URL;

export async function interpretUserSpeech(transcript, context) {
  console.log('[AI] interpretUserSpeech called');
  console.log('[AI] transcript:', transcript);
  console.log('[AI] context:', context);

  if (!ASSISTANT_FUNCTION_URL) {
    console.error(
      '[AI] REACT_APP_CATALYST_ASSISTANT_FUNCTION_URL is not set at build time.'
    );
    throw new Error('Assistant function URL is not configured.');
  }

  console.log('[AI] Calling Catalyst function:', ASSISTANT_FUNCTION_URL);

  let response;
  try {
    response = await fetch(ASSISTANT_FUNCTION_URL, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ transcript, context }),
    });
  } catch (networkErr) {
    // This branch fires for CORS failures, DNS issues, or the request
    // never reaching the server at all — the browser blocks it client-side.
    console.error('[AI] Network-level fetch failure (often CORS):', networkErr);
    throw networkErr;
  }

  console.log('[AI] Response status:', response.status);

  if (!response.ok) {
    const bodyText = await response.text().catch(() => '(could not read body)');
    console.error('[AI] Function returned non-OK status. Body:', bodyText);
    throw new Error(`Assistant function error: ${response.status}`);
  }

  const data = await response.json();
  console.log('[AI] Parsed response from function:', data);
  return data;
}

export default { interpretUserSpeech };
